import json, os
H = os.path.dirname(os.path.abspath(__file__))
W = []
def T(side, *p): return {"side": side, "polities": list(p)}
def F(label, *pts): return {"path": [list(x) for x in pts], "label": label}
def M(side, commander, label, *pts): return {"side": side, "commander": commander, "label": label, "path": [list(x) for x in pts]}
def E(name, kind, lon, lat, year, winner, text): return {"name": name, "kind": kind, "lon": lon, "lat": lat, "year": year, "winner": winner, "text": text}
def S(year, label, title, text, territories, fronts, moves, events):
    return dict(year=year, label=label, title=title, text=text, territories=territories, fronts=fronts, moves=moves, events=events)

# ---------------- 1. War of the Pacific ----------------
