  S(1895,"Jan to Feb 1895","Weihaiwei",
    "The Second Army landed on the tip of Shandong and took the land forts of Weihaiwei from behind, while torpedo boats raided the trapped Beiyang Fleet. Admiral Ding Ruchang surrendered the fleet on 12 February and took his own life. Japanese armies also advanced on Yingkou in Manchuria, and Beijing sued for peace.",
    sj(0), [],
    [M(0,"Oyama Iwao","Shandong landing",(121.6,38.92),(122.5,37.6),(122.42,37.17),WHW),
     M(0,"Nozu Michitsura","Advance on Yingkou",(122.75,40.85),(122.24,40.67))],
    [E("Battle of Weihaiwei","siege",WHW[0],WHW[1],1895,0,"The Beiyang Fleet surrenders; China has no navy left in the north.")]),
